mapper.select:
select
ciis.REGIST_SEQNO           registSeqno,
ciis.REGIST_BANK_CODE       registBankCode,
ciis.CHB_SUBMIT_DEADLINE    chbSubmitDeadline,
ciis.PRD_REGIST_CODE        prdRegistCode,
ciis.INDENTIFY_MARK         indentifyMark,
ciis.CCY                    ccy,
ciis.HOLD_DATE              holdDate,
ciis.AMOUNT                 amount,
(case when substring(ciis.AMOUNT,1,1) = '.' then concat_ws('',0, ciis.AMOUNT)
else ciis.AMOUNT end) amountExportExcel,
ciis.QTY                    qty,
(case when substring(ciis.QTY,1,1) = '.' then concat_ws('',0, ciis.QTY)
else ciis.QTY end) qtyExportExcel,
ciis.CNY_AMT                cnyAmt,
(case when substring(ciis.CNY_AMT,1,1) = '.' then concat_ws('',0, ciis.CNY_AMT)
else ciis.CNY_AMT end) cnyAmtExportExcel,
ciis.REMARK                 remark,
ciis.SUBMIT_DEADLINE        submitDeadline,
ciis.WORKFLOW_ID            workflowId,
ciis.SEND_STATUS            sendStatus,
ciis.STATUS_DATE            statusDate,
ciis.STATUS                 status,
ciis.CREATE_USER            createUser,
ciis.CREATE_TIME            createTime,
ciis.UPDATE_USER            updateUser,
ciis.UPDATE_TIME            updateTime,
ciis.ORG_CODE               orgCode,
ciis.DEPT_CODE              deptCode,
ciis.SUBMIT_TIME            submitTime,
ciis.SUMIT_SEQ				sumitSeq,
ciis.CHECK_SEQNO			checkSeqno,
crc.IS_LOGIC_CHECK			isLogicCheck,
ciis.SUBMIT_FEEDBACK_STATUS submitFeedbackStatus,
ciis.SUBMIT_SEND_STATUS    submitSendStatus
from CHB_INVESTHOLD_INFO_SUB ciis
left join CHB_REPORT_CHECK crc
on ciis.CHECK_SEQNO = crc.CHECK_SEQNO


		DATE_FORMAT(ciis.CHB_SUBMIT_DEADLINE,'%Y-%m-%d') >= #{submitDeadLineStart,jdbcType=VARCHAR}


		and DATE_FORMAT(ciis.CHB_SUBMIT_DEADLINE,'%Y-%m-%d') <= #{submitDeadLineEnd,jdbcType=VARCHAR}



			#{item,jdbcType=VARCHAR}




			#{item,jdbcType=VARCHAR}



		and DATE_FORMAT(ciis.UPDATE_TIME,'%Y-%m-%d') >= #{updateTimeStart,jdbcType=VARCHAR}


		and DATE_FORMAT(ciis.UPDATE_TIME,'%Y-%m-%d') <= #{updateTimeEnd,jdbcType=VARCHAR}


		and DATE_FORMAT(ciis.SUBMIT_TIME,'%Y-%m-%d') >= #{submitDateStart,jdbcType=VARCHAR}


		and DATE_FORMAT(ciis.SUBMIT_TIME,'%Y-%m-%d') <= #{submitDateEnd,jdbcType=VARCHAR}



			#{submitFeedbackStatus,jdbcType=VARCHAR}



		and ciis.REGIST_BANK_CODE like concat_ws('','%',#{registBankCode,jdbcType=VARCHAR},'%')



			#{item,jdbcType=VARCHAR}



		and ciis.INDENTIFY_MARK like concat_ws('','%',#{indentifyMark,jdbcType=VARCHAR},'%')


		and ciis.HOLD_DATE >= STR_TO_DATE(#{holdDateStart,jdbcType=VARCHAR},'%Y-%m-%d')


		and ciis.HOLD_DATE <= STR_TO_DATE(#{holdDateEnd,jdbcType=VARCHAR},'%Y-%m-%d')



			#{item,jdbcType=VARCHAR}




			ciis.PRD_REGIST_CODE = #{investDto.prdRegistCode,jdbcType=VARCHAR}
			and ciis.REGIST_BANK_CODE = #{investDto.registBankCode,jdbcType=VARCHAR}
			and ciis.INDENTIFY_MARK = #{investDto.indentifyMark,jdbcType=VARCHAR}
			and ciis.CCY = #{investDto.ccy,jdbcType=VARCHAR}
			and DATE_FORMAT(ciis.HOLD_DATE,'%Y-%m-%d') = DATE_FORMAT(#{investDto.holdDate,jdbcType=DATE},'%Y-%m-%d')


					and ciis.SEND_STATUS in('02','03')


					and ciis.SEND_STATUS = #{investDto.sendStatus,jdbcType=VARCHAR}








order by ciis.REGIST_SEQNO,ciis.HOLD_DATE desc

select
