from CHB_INVESTHOLD_INFO_SUB ciis


		DATE_FORMAT(ciis.CHB_SUBMIT_DEADLINE,'%Y-%m-%d') >= #{submitDeadLineStart,jdbcType=VARCHAR}


		and DATE_FORMAT(ciis.CHB_SUBMIT_DEADLINE,'%Y-%m-%d') <= #{submitDeadLineEnd,jdbcType=VARCHAR}



			#{item,jdbcType=VARCHAR}




			#{item,jdbcType=VARCHAR}



		and DATE_FORMAT(ciis.UPDATE_TIME,'%Y-%m-%d') >= #{updateTimeStart,jdbcType=VARCHAR}


		and DATE_FORMAT(ciis.UPDATE_TIME,'%Y-%m-%d') <= #{updateTimeEnd,jdbcType=VARCHAR}


		and DATE_FORMAT(ciis.SUBMIT_TIME,'%Y-%m-%d') >= #{submitDateStart,jdbcType=VARCHAR}


		and DATE_FORMAT(ciis.SUBMIT_TIME,'%Y-%m-%d') <= #{submitDateEnd,jdbcType=VARCHAR}



		and ciis.REGIST_BANK_CODE like concat(concat('%',#{registBankCode,jdbcType=VARCHAR}),'%')




			#{item,jdbcType=VARCHAR}



		and ciis.INDENTIFY_MARK like concat(concat('%',#{indentifyMark,jdbcType=VARCHAR}),'%')


		and ciis.HOLD_DATE >= STR_TO_DATE(#{holdDateStart,jdbcType=VARCHAR},'%Y-%m-%d')


		and ciis.HOLD_DATE <= STR_TO_DATE(#{holdDateEnd,jdbcType=VARCHAR},'%Y-%m-%d')

