		SEND_STATUS = #{sendStatus},

	SUBMIT_TIME = NOW(),
	UPDATE_TIME = NOW()



		PRD_REGIST_CODE = #{investDto.prdRegistCode,jdbcType=VARCHAR}
		and REGIST_BANK_CODE = #{investDto.registBankCode,jdbcType=VARCHAR}
		and INDENTIFY_MARK = #{investDto.indentifyMark,jdbcType=VARCHAR}
		and CCY = #{investDto.ccy,jdbcType=VARCHAR}
		and DATE_FORMAT(HOLD_DATE,'%Y-%m-%d') = DATE_FORMAT(#{investDto.holdDate,jdbcType=DATE},'%Y-%m-%d')
		and SEND_STATUS = '01'

