sub.SEND_STATUS = #{sendStatus},
sub.SUMIT_SEQ = #{equityRegist.sumitSeq},
sub.SUBMIT_TIME = now(), sub.UPDATE_TIME = now()
where sub.REGIST_SEQNO = #{equityRegist.registSeqno}
