mapper.update:
UPDATE CHB_INVESTHOLD_INFO_SUB as A, ( select REGIST_BANK_CODE,INDENTIFY_MARK,PRD_REGIST_CODE,HOLD_DATE,CCY,CHECK_SEQNO,REGIST_SEQNO from ( select TEMP.REGIST_BANK_CODE ,TEMP.INDENTIFY_MARK ,TEMP.PRD_REGIST_CODE ,TEMP.HOLD_DATE ,TEMP.CCY ,TEMP.CHECK_SEQNO,TEMP.REGIST_SEQNO from (
SELECT #{item.registBankCode} REGIST_BANK_CODE, #{item.indentifyMark} INDENTIFY_MARK, #{item.prdRegistCode,jdbcType=VARCHAR} PRD_REGIST_CODE, #{item.holdDate} HOLD_DATE, #{item.ccy} CCY, #{item.checkSeqno} CHECK_SEQNO, #{item.registSeqno} REGIST_SEQNO FROM dual
) TEMP,CHB_INVESTHOLD_INFO_SUB CII where CII.REGIST_BANK_CODE = TEMP.REGIST_BANK_CODE AND CII.INDENTIFY_MARK = TEMP.INDENTIFY_MARK AND CII.PRD_REGIST_CODE = TEMP.PRD_REGIST_CODE AND CII.HOLD_DATE = TEMP.HOLD_DATE AND CII.CCY = TEMP.CCY AND CII.SEND_STATUS = '01' ) de ) AS B set A.CHECK_SEQNO = B.CHECK_SEQNO where A.REGIST_SEQNO = B.REGIST_SEQNO ;


	update CHB_INVESTHOLD_INFO_SUB  sub
	set
	sub.SUBMIT_SEND_STATUS = #{item.submitSendStatus}
	where
	sub.SUMIT_SEQ = #{item.sumitSeq}

;

